        color: var(--text);
      }

      .footer-note {
        margin-top: 1.35rem;
        color: var(--muted);
        font-size: 0.95rem;
      }

      @media (max-width: 640px) {
        .shell {
          padding: 3.5rem 1rem 4rem;
        }

        .details > summary {
          padding: 1.05rem 1rem;
        }

        .answer {
          padding-inline: 1rem;
