    <a class="skip-link" href="#main">Skip to main content</a>
    <div id="root"></div>

    <script>
      const faqs = [
        {
          question: "Why do cats purr?",
          answer: [
            "Cats purr when they feel content, but they also purr to calm themselves, ask for comfort, or cope with stress.",
            "The sound comes from rapid muscle movements around the larynx and diaphragm.",
          ],
        },
        {
          question: "How much sleep do cats need?",
          answer: [
            "Most cats sleep 12 to 16 hours a day, and some kittens or senior cats sleep even more.",
            "That extra rest helps them save energy for hunting, playing, and exploring.",
