          answer: [
            "Cats may bring toys or prey because they are sharing a successful hunt or practicing hunting behavior.",
            "It is usually a sign of trust, even if the present is a little surprising.",
          ],
        },
      ];

      function DisclosureItem({ question, answer, index }) {
        const content = answer.map((paragraph) => `<p>${paragraph}</p>`).join("");

        return `
          <div class="example">
            <details class="details">
              <summary id="faq-${index}-summary"> ${question} </summary>
              <div class="answer" aria-labelledby="faq-${index}-summary">
                ${content}
              </div>
            </details>
          </div>
        `;
      }

      function App() {
        return `
          <main id="main" class="shell">
            <header class="hero">
              <p class="eyebrow">Cat care FAQ</p>
